CODE = ".scroll"
# Airflow 2.8.1's React Flow has onlyRenderVisibleElements=true, so '.react-flow__node' counts only on-screen
# nodes (6 of 8 fit) and a count of 8 never arrives. Instead: some node is drawn AND the last task's name is on the page.
# Airflow 2.8 renders the grid/graph inside a shadow root and React Flow only draws visible nodes,
# so look for the task name in every shadow root as well as the light DOM.
NODES = lambda last_task: ("(()=>{const X=" + repr(last_task) + ";const has=r=>r.textContent.includes(X)||"
                           "[...r.querySelectorAll('*')].some(e=>e.shadowRoot&&has(e.shadowRoot));return has(document.body)})()")
CANV = lambda n: f"document.querySelectorAll('canvas').length>={n}"
row = lambda n: f'.row[data-line="{n}"]'

def page(label, name, step, cap, hold, acts=(), ready=DOC):
    return {"label": label, "nav": ST + name + ".html", "ready": ready, "step": step, "cap": cap, "hold": hold, "acts": list(acts)}

