# ── Chat take (R9). Bedrock budget: 16 used; connect = 1 call, each question = 1. Default 2 questions (19/20). ──
import os as _os
IB = "https://localhost/hi-ee/#/instant-bi"
PICKER_ROWS = "!!document.querySelector('.ant-modal.fileBrowser-drawer tr.ant-table-row')"
MODEL_ROW = "!!document.querySelector('.ant-modal.fileBrowser-drawer tr.ant-table-row-level-1')"
CONNECTED = "!document.querySelector('.ant-modal.fileBrowser-drawer') && !!document.querySelector('.instant-bi-metadata-selected')"
SUGGESTED = "document.querySelectorAll('.suggestion-item').length>=1 || !document.querySelector('.chat-suggestions__loading-bar')"
ANSWERED = ("(()=>{const bot=[...document.querySelectorAll('.message-container__bot-content')];const last=bot[bot.length-1];if(!last)return false;"
            "const idle=!document.querySelector('.instant-bi-beat-loader')&&!document.querySelector('[data-testid=ib-chat-abort-button]')&&!document.querySelector('#ib-search-input').disabled;"
            "const viz=last.querySelector('.ib-live-preview svg, .ib-live-preview canvas, .chart-container svg, .chart-container canvas, .ib-data-table');"
            "const err=last.querySelector('.ib-response-error, .message-container__chat-message--error');return idle&&(!!viz||!!err)})()")

QUESTIONS = [
    ("Which payment format has the highest laundering rate?",
     "ACH: 3,828 laundering transfers out of 599,685 (0.64%). Checked against the snapshot: correct."),
    ("Build a dashboard of transfers per day",
     "A bar chart of transfers per accepted day, straight from monitor_daily. All eight values match the data."),
    ("Which payment currency has the highest laundering rate?",
     "Saudi Riyal at 0.34%, then Euro 0.10% and US Dollar 0.09%. Correct against the snapshot."),
][: int(_os.environ.get("CHAT_QUESTIONS", "2"))]

def ask(i, q, verdict):
    return {"label": f"R9_Q{i}", "step": "Run 4 of 4", "cap": f"Question {i}: {q}", "hold": 4,
            "acts": [("click", "#ib-search-input"), ("sleep", 0.5), ("type", "#ib-search-input", q), ("sleep", 1.2),
                     ("key", "Enter"), ("ready", ANSWERED, 150), ("sleep", 2.5),
                     ("cap", "Run 4 of 4", verdict), ("sleep", 11)]}

CHAT = [
    {"label": "R9_OPEN", "nav": IB, "ready": "!!document.querySelector('#ib-search-input')", "ready_timeout": 40, "settle": 3,
     "step": "Run 4 of 4", "cap": "Instant BI: ask the data in plain English. The chat runs on Claude Haiku 4.5 via Amazon Bedrock.", "hold": 8},
    {"label": "R9_CONNECT", "step": "Run 4 of 4", "cap": "Connect the semantic model: AML BQ2 analysis, one cube over the six marts.", "hold": 4,
     "acts": [("clickxy", 223, 433), ("ready", PICKER_ROWS, 20), ("sleep", 1.5),
              ("clickxy", 148, 136), ("ready", MODEL_ROW, 20), ("sleep", 1.5),
              ("dblclickxy", 148, 178), ("ready", CONNECTED, 40), ("sleep", 1),
              ("cap", "Run 4 of 4", "Connected. Instant suggests a few questions; we ask our own."),
              ("ready", SUGGESTED, 30), ("sleep", 4)]},
] + [ask(i + 1, q, v) for i, (q, v) in enumerate(QUESTIONS)]

TAKES["chat"] = CHAT
